#define MAX_STEPS 500
#define FAR_DIST 100.0

#define GAMMA 2.2

float aabb_intersect(vec3 p, vec3 d, out vec3 n)
{
    const float eps = 0.001;
    vec3 deltas = (step(0.0, d) - fract(p)) / d;
    float t;

    if(deltas.x < deltas.y)
    {
        t = deltas.x;
        n = vec3(1.0, 0.0, 0.0);
    } else
    {
        t = deltas.y;
        n = vec3(0.0, 1.0, 0.0);
    }

    if(t > deltas.z)
    {
        t = deltas.z;
        n = vec3(0.0, 0.0, 1.0);
    }

    t = max(t, eps);

    return t;
}

float shading(vec3 p, vec3 n, vec3 ld)
{
    return max(dot(n, ld), 0.01);
}

float fog(vec3 p, float d1, float d2)
{
    return smoothstep(d1, d2, (1.0 - length(p.xz) / FAR_DIST) );
}

vec3 text(int id, vec2 uv)
{
    uv = floor(fract(uv) * 20.0);
    float rand1 = floor(hash12(uv) * 3.0) * 0.1;
    float rand2 = floor(hash12(uv.xx) * 3.0) * 0.4;

    const vec3 dirt_col  = vec3(0.45, 0.31, 0.22);
    const vec3 grass_col = vec3(0.34, 0.58, 0.27);

    switch (id)
    {
        case 0:

        if(uv.y > 15.0 + rand2) return grass_col  * (vec3(1.0) + rand1);
        else                    return dirt_col   * (vec3(1.0) + rand1);

        case 1:
        return grass_col * (vec3(1.0) + rand1);
    }
    return vec3(0.0);
}

vec3 triplanar(vec3 p, vec3 n, float k)
{
    vec3 w = vec3(
        abs(dot(LEFT, n)),
        abs(dot(UP, n)),
        abs(dot(FORWARD, n))
    );

   w = pow(w, vec3(k));
   w = w / (w.x + w.y + w.z);


    vec3 o  = text(0, p.zy) * w.x;
         o += text(1, p.xz) * w.y;
         o += text(0, p.xy) * w.z;

    return o;
}

//based on: https://medium.com/@calebleak/raymarching-voxel-rendering-58018201d9d6
vec3 grid_march(vec3 ro, vec3 rd)
{
    float d = 0.0;
    vec3 p;
    vec3 n;
    bool hit;

    for(int i = 0; i < MAX_STEPS; i++)
    {               
        if(d > FAR_DIST) break;

        p = ro + rd * d;

        float h = floor(perlin(floor(p.xz) * 0.1) * 10.0);

        if( p.y < h )
        {
            hit = true;
            break;
        }

        d += aabb_intersect(p, rd, n);
    }

    //render
    vec3 ld = normalize(vec3(0.2, 1.0, 0.8));
    vec3 col = vec3(0.3, 0.7, 1.0);

    if(hit)
    {
        col = triplanar(p, n, 20.0) * pow(shading(p, n, ld), 1.0/GAMMA);
        col = mix( vec3(0.3, 0.7, 1.0), col, fog(p - ro, 0.0, 0.33) );
    }

    return col;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.yy;
    uv -= vec2(0.88, 0.5);

    vec3 ro = vec3(4.5);
    vec3 rd = normalize(vec3(uv, 0.0) - vec3(0.0, 0.0, 1.0));

    //player controls
    vec3 rot = texelFetch(iChannel0, ivec2(1), 0).xyz;
    vec3 pos = texelFetch(iChannel0, ivec2(0), 0).xyz;
    rd = rotate(rd, rot);
    ro += pos;

    vec3 col = grid_march(ro, rd);

    // Output to screen
    fragColor = vec4(col,1.0);
    //fragColor = texture(iChannel0, fragCoord/iResolution.xy); //test inputs
}

#define VIEW_ROT vec3(iMouse.y / iResolution.y * 1.57 -  0.8, -(iMouse.x / iResolution.x * 3.14 - 1.57), 0.0)

#define LEFT    vec3(1.0, 0.0, 0.0) 
#define UP      vec3(0.0, 1.0, 0.0)
#define FORWARD vec3(0.0, 0.0, 1.0)

//hash22 from: https://www.shadertoy.com/view/ldc3RB
vec2 hash22(vec2 p)
{
    p = vec2( dot(p,vec2(127.1,311.7)),
			  dot(p,vec2(269.5,183.3)));
    return -1.0 + 2.0 * fract(sin(p)*43758.5453123);
}

//hash12 from: https://www.shadertoy.com/view/ldc3RB
float hash12(vec2 p)
{
	float h = dot(p,vec2(127.1,311.7));

    return -1.0 + 2.0 * fract(sin(h)*43758.5453123);
}


float perlin(vec2 uv) {
    vec2 i = floor(uv);
    vec2 f = fract(uv);

    //cubic hermite curve: f(x) = x*x*(3.0-2.0*x)
    //vec2 t = smoothstep(vec2(0.), vec2(1.), f);

    //quintic interpolation curve:
    vec2 t = f*f*f*(f*(f*6.-15.)+10.);

    return mix( mix(dot(hash22(i                ), f                ), dot(hash22(i + vec2(1., 0.) ), f - vec2(1.,0.) ), t.x),
                mix(dot(hash22(i + vec2(0., 1.) ), f - vec2(0., 1.) ), dot(hash22(i + vec2(1., 1.) ), f - vec2(1.,1.) ), t.x),
                t.y);
}

vec3 rotate(vec3 p, vec3 angle)
{
    return (vec4(p, 1.0) * mat4(
        vec4(1.0,        0.0,         0.0, 0.0),
        vec4(0.0, cos(angle.x), -sin(angle.x), 0.0),
        vec4(0.0, sin(angle.x),  cos(angle.x), 0.0),
        vec4(0.0,          0.0,           0.0, 1.0)
    ) * mat4(
        vec4( cos(angle.y), 0.0, sin(angle.y), 0.0),
        vec4(          0.0, 1.0,          0.0, 0.0),
        vec4(-sin(angle.y), 0.0, cos(angle.y), 0.0),
        vec4(          0.0, 0.0,          0.0, 1.0) 
    ) * mat4(
        vec4(cos(angle.z), -sin(angle.z), 0.0, 0.0),
        vec4(sin(angle.z),  cos(angle.z), 0.0, 0.0),
        vec4(         0.0,           0.0, 1.0, 0.0),
        vec4(         0.0,           0.0, 0.0, 1.0)
    )).xyz;
}

///////////////////////
///Player Constrols
//////////////////////

#define PLAYER_SPEED 0.05
#define CAMERA_SENSITIVITY 1.8
#define KEY_A 65
#define KEY_S 83
#define KEY_D 68
#define KEY_W 87
#define KEY_Q 81
#define KEY_E 69
#define KEY_LEFT  37
#define KEY_UP    38
#define KEY_RIGHT 39
#define KEY_DOWN  40
#define KEY_SPACE 32
#define KEY_SHIFT 16

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   
    vec3 pos;
    vec3 rot;
    vec2 m_click;

    pos     = texelFetch(iChannel0, ivec2(0), 0).xyz;
    rot     = texelFetch(iChannel0, ivec2(1), 0).xyz;
    m_click = texelFetch(iChannel0, ivec2(2), 0).xy;


    if(iMouse.w > 0.0)
    {
        m_click = iMouse.xy / iResolution.xy;
    }

    vec2 drag = iMouse.xy / iResolution.xy - m_click;

    rot = vec3(drag.y, -drag.x, 0.0) * CAMERA_SENSITIVITY;

    //need implement mouse delta before
    //rot.y += texelFetch(iChannel1, ivec2(KEY_Q, 0), 0).x * 0.1;
    //rot.y -= texelFetch(iChannel1, ivec2(KEY_E, 0), 0).x * 0.1;

    vec3 forward = rotate(FORWARD, rot);      
    vec3 right = cross(UP, forward);

    vec3 delta_pos;

    //awasd
    delta_pos -= forward * texelFetch(iChannel1, ivec2(KEY_W, 0), 0).x * PLAYER_SPEED;
    delta_pos -= right   * texelFetch(iChannel1, ivec2(KEY_A, 0), 0).x * PLAYER_SPEED;
    delta_pos += forward * texelFetch(iChannel1, ivec2(KEY_S, 0), 0).x * PLAYER_SPEED;
    delta_pos += right   * texelFetch(iChannel1, ivec2(KEY_D, 0), 0).x * PLAYER_SPEED;

    //arrows
    delta_pos -= forward * texelFetch(iChannel1, ivec2(KEY_UP   , 0), 0).x * PLAYER_SPEED;
    delta_pos -= right   * texelFetch(iChannel1, ivec2(KEY_LEFT , 0), 0).x * PLAYER_SPEED;
    delta_pos += forward * texelFetch(iChannel1, ivec2(KEY_DOWN , 0), 0).x * PLAYER_SPEED;
    delta_pos += right   * texelFetch(iChannel1, ivec2(KEY_RIGHT, 0), 0).x * PLAYER_SPEED;

    delta_pos.y -= texelFetch(iChannel1, ivec2(KEY_SHIFT, 0), 0).x * PLAYER_SPEED;
    delta_pos.y += texelFetch(iChannel1, ivec2(KEY_SPACE, 0), 0).x * PLAYER_SPEED;

    pos += delta_pos;

    ivec2 cord = ivec2(fragCoord);

    fragColor = vec4(rot.xy, 0.0, 1.0);
    if(cord.x == 0) fragColor = vec4(pos, 1.0);
    if(cord.x == 1) fragColor = vec4(rot, 1.0);
    if(cord.x == 2) fragColor = vec4(m_click, 0.0, 1.0);
}
